def backfill_chemical_inventory_and_legacy_coa_hashes(apps, schema_editor):
    ChemicalBatch = apps.get_model("ca", "ChemicalBatch")
    ChemicalInventoryMovement = apps.get_model("ca", "ChemicalInventoryMovement")
    ChemicalCoA = apps.get_model("ca", "ChemicalCoA")
    ChemicalCustodyEvent = apps.get_model("ca", "ChemicalCustodyEvent")
    ChemicalAnalysisProcess = apps.get_model("ca", "ChemicalAnalysisProcess")
    ChemicalWorkflowEvent = apps.get_model("ca", "ChemicalWorkflowEvent")
    BatchTestResult = apps.get_model("ca", "BatchTestResult")
    ChemicalAnalysisInput = apps.get_model("ca", "ChemicalAnalysisInput")
    database = schema_editor.connection.alias

    # Existing CoAs were sealed using version 3 payloads. Keep them verifiable;
    # newly generated CoAs use the version 4 result/method snapshot payload.
    ChemicalCoA.objects.using(database).all().update(hash_version=3)

    for batch in ChemicalBatch.objects.using(database).all().iterator(chunk_size=500):
        movements = ChemicalInventoryMovement.objects.using(database)
        if movements.filter(batch_id=batch.pk).exists():
            continue

        balance = Decimal("0")
        received = Decimal(str(batch.quantity_received or 0))
        created_at = batch.created_at or django.utils.timezone.now()
        if received > 0:
            balance += received
            movements.create(
                batch_id=batch.pk,
                movement_type="RECEIPT",
                quantity_delta=received,
                quantity_after=balance,
                unit=batch.unit or "kg",
                actor_id=batch.received_by_id,
                idempotency_key=f"legacy:{batch.pk}:receipt",
                notes="Opening balance migrated from the received chemical batch.",
                created_at=created_at,
            )

        historical = []
        if batch.quantity_utilized:
            historical.append((batch.utilized_at or batch.updated_at or created_at, "UTILIZATION", Decimal(str(batch.quantity_utilized)), batch.utilized_by_id))
        if batch.quantity_returned:
            historical.append((batch.returned_at or batch.updated_at or created_at, "RETURN", Decimal(str(batch.quantity_returned)), batch.returned_by_id))
        for occurred_at, movement_type, requested_quantity, actor_id in sorted(historical, key=lambda item: (item[0], item[1])):
            applied_quantity = min(max(requested_quantity, Decimal("0")), balance)
            if applied_quantity <= 0:
                continue
            balance -= applied_quantity
            legacy_note = f"Historical {movement_type.lower()} amount migrated from the batch record."
            if applied_quantity != requested_quantity:
                legacy_note += f" Requested {requested_quantity}; capped at remaining recorded balance {applied_quantity}."
            movements.create(
                batch_id=batch.pk,
                movement_type=movement_type,
                quantity_delta=-applied_quantity,
                quantity_after=balance,
                unit=batch.unit or "kg",
                actor_id=actor_id,
                idempotency_key=f"legacy:{batch.pk}:{movement_type.lower()}",
                notes=legacy_note,
                created_at=occurred_at,
            )

        if not ChemicalCustodyEvent.objects.using(database).filter(
            batch_id=batch.pk
        ).exists():
            ChemicalCustodyEvent.objects.using(database).create(
                batch_id=batch.pk,
                event_type="RECEIVED",
                actor_id=batch.received_by_id,
                to_location=(batch.location.name if batch.location_id else ""),
                remarks="Initial custody record migrated from the received batch.",
                occurred_at=created_at,
            )

    for process in ChemicalAnalysisProcess.objects.using(database).select_related("batch").iterator(chunk_size=500):
        if not ChemicalWorkflowEvent.objects.using(database).filter(process_id=process.pk).exists():
            ChemicalWorkflowEvent.objects.using(database).create(
                process_id=process.pk,
                batch_id=process.batch_id,
                analysis_request_id=process.analysis_request_id,
                event_type="legacy_workflow_state",
                action="workflow state captured during audit migration",
                to_status=str(process.status or ""),
                actor_id=process.initiated_by_id,
                details={"migrated": True},
                occurred_at=process.updated_at or process.created_at or django.utils.timezone.now(),
            )

    for result in BatchTestResult.objects.using(database).select_related(
        "parameter", "parameter__method"
    ).iterator(chunk_size=500):
        if not result.parameter_id:
            continue
        parameter = result.parameter
        method = parameter.method if parameter.method_id else None
        specification_snapshot = {
            "id": parameter.pk,
            "chemical_id": parameter.chemical_id,
            "treatment_plant_id": parameter.treatment_plant_id,
            "parameter_name": parameter.parameter_name,
            "unit": parameter.unit,
            "min_limit": parameter.min_limit,
            "max_limit": parameter.max_limit,
            "version": parameter.version,
            "is_required": parameter.is_required,
            "is_active": getattr(parameter, "is_active", True),
            "requires_instrument": getattr(parameter, "requires_instrument", False),
            "migrated_snapshot": True,
        }
        method_snapshot = {}
        if method:
            method_snapshot = {
                "id": str(method.pk),
                "name": method.method,
                "version": method.version,
                "reference": method.kebs_reference,
                "formula": method.formula,
                "inputs_structure": method.inputs_structure,
                "unit": method.unit,
                "rounding_precision": method.rounding_precision,
                "formula_hash": method.formula_hash,
                "migrated_snapshot": True,
            }
        BatchTestResult.objects.using(database).filter(pk=result.pk).update(
            specification_snapshot=specification_snapshot,
            method_snapshot=method_snapshot,
            revision_number=1,
        )

    for record in ChemicalAnalysisInput.objects.using(database).select_related(
        "test_result", "test_result__parameter", "test_result__parameter__method"
    ).iterator(chunk_size=500):
        if record.method_snapshot:
            continue
        parameter = record.test_result.parameter if record.test_result_id else None
        method = parameter.method if parameter and parameter.method_id else None
        if method:
            ChemicalAnalysisInput.objects.using(database).filter(pk=record.pk).update(
                method_snapshot={
                    "id": str(method.pk),
                    "name": method.method,
                    "version": method.version,
                    "reference": method.kebs_reference,
                    "formula": method.formula,
                    "inputs_structure": method.inputs_structure,
                    "unit": method.unit,
                    "rounding_precision": method.rounding_precision,
                    "formula_hash": method.formula_hash,
                    "migrated_snapshot": True,
                }
            )


